SET search_path TO ava, public;

ALTER TABLE owner_alerts ADD COLUMN IF NOT EXISTS action      text;
ALTER TABLE owner_alerts ADD COLUMN IF NOT EXISTS acted_at    timestamptz;

CREATE OR REPLACE FUNCTION queue_owner_alert(
  p_kind text, p_urgent boolean, p_text text,
  p_buttons jsonb DEFAULT NULL, p_booking uuid DEFAULT NULL, p_ref jsonb DEFAULT '{}'::jsonb
) RETURNS bigint
LANGUAGE sql AS $$
  INSERT INTO ava.owner_alerts (kind, urgent, text, buttons, booking_id, ref, deliver_after)
  VALUES (p_kind, p_urgent, p_text, p_buttons, p_booking, COALESCE(p_ref, '{}'::jsonb),
          CASE WHEN p_urgent THEN now() ELSE ava.quiet_ends_at(now()) END)
  RETURNING id
$$;

CREATE OR REPLACE FUNCTION fmt_local(ts timestamptz) RETURNS text
LANGUAGE sql STABLE AS $$
  SELECT trim(to_char(ts AT TIME ZONE (ava.setting('timezone') #>> '{}'), 'Dy Mon FMDD, FMHH12:MI AM'))
$$;

CREATE OR REPLACE FUNCTION create_booking_request(
  p_client uuid, p_service text, p_start timestamptz, p_end timestamptz,
  p_format text, p_phone text, p_topic text, p_budget text, p_timeline text, p_notes text,
  p_channel text, p_kind text DEFAULT 'new', p_replaces uuid DEFAULT NULL, p_urgent_words boolean DEFAULT false
) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  buf      interval := make_interval(mins => (ava.setting('buffer_minutes') #>> '{}')::int);
  timers   jsonb    := ava.setting('approval_timers');
  urg_days int      := (ava.setting('urgent_days') #>> '{}')::int;
  v_urgent boolean;
  v_reason text;
  v_svc    ava.services;
  v_client ava.clients;
  v_id     uuid;
  v_t      jsonb;
  v_alert  bigint;
  v_text   text;
  v_orig   ava.bookings;
BEGIN
  IF EXISTS (
    SELECT 1 FROM ava.bookings b
    WHERE b.status IN ('pending','approved')
      AND (p_replaces IS NULL OR b.id <> p_replaces)
      AND tstzrange(b.start_at - buf, b.end_at + buf) && tstzrange(p_start, p_end)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'slot_taken',
      'message', 'That time was just requested by someone else. Check open slots again.');
  END IF;

  v_urgent := (p_start - now()) <= make_interval(days => urg_days) OR COALESCE(p_urgent_words, false);
  v_reason := CASE
    WHEN COALESCE(p_urgent_words, false) THEN 'client used urgency words'
    WHEN (p_start - now()) <= make_interval(days => urg_days) THEN 'call within ' || urg_days || ' days'
  END;
  v_t := timers -> (CASE WHEN v_urgent THEN 'urgent' ELSE 'standard' END);

  SELECT * INTO v_svc FROM ava.services WHERE lower(name) = lower(p_service) LIMIT 1;
  SELECT * INTO v_client FROM ava.clients WHERE id = p_client;

  INSERT INTO ava.bookings (client_id, service_id, kind, replaces_booking_id, start_at, end_at,
    call_format, call_phone, topic, budget_text, timeline_text, notes, channel, urgent, urgent_reason,
    checkpoint_due_at, expires_at)
  VALUES (p_client, v_svc.id, COALESCE(p_kind, 'new'), p_replaces, p_start, p_end,
    p_format, NULLIF(p_phone, ''), p_topic, NULLIF(p_budget, ''), NULLIF(p_timeline, ''), NULLIF(p_notes, ''),
    p_channel, v_urgent, v_reason,
    ava.add_active_minutes(now(), (v_t ->> 'checkpoint')::int),
    ava.add_active_minutes(now(), (v_t ->> 'expire')::int))
  RETURNING id INTO v_id;

  IF p_replaces IS NOT NULL THEN
    SELECT * INTO v_orig FROM ava.bookings WHERE id = p_replaces;
  END IF;

  v_text := CASE WHEN v_urgent THEN '🚨 URGENT ' ELSE '' END
    || CASE WHEN p_kind = 'reschedule' THEN '🔁 Reschedule request' ELSE '📅 New booking request' END || E'\n\n'
    || 'Client: ' || COALESCE(v_client.name, 'Unknown')
      || CASE WHEN v_client.is_existing THEN ' (existing client)' ELSE '' END || E'\n'
    || COALESCE('Company: ' || v_client.company || E'\n', '')
    || 'Service: ' || COALESCE(v_svc.name, p_service, 'Not specified') || E'\n'
    || CASE WHEN v_orig.id IS NOT NULL THEN 'Moving from: ' || ava.fmt_local(v_orig.start_at) || E'\n' ELSE '' END
    || 'When: ' || ava.fmt_local(p_start) || ' (' || (extract(epoch FROM p_end - p_start) / 60)::int || ' min)' || E'\n'
    || 'Format: ' || CASE WHEN p_format = 'meet' THEN 'Google Meet' ELSE 'Phone call to ' || COALESCE(NULLIF(p_phone, ''), 'number not given') END || E'\n'
    || 'Email: ' || COALESCE(v_client.email, '-') || E'\n'
    || 'Need: ' || COALESCE(p_topic, '-') || E'\n'
    || COALESCE('Budget: ' || NULLIF(p_budget, '') || E'\n', '')
    || COALESCE('Timeline: ' || NULLIF(p_timeline, '') || E'\n', '')
    || COALESCE('Found you via: ' || v_client.found_via || E'\n', '')
    || COALESCE('Notes: ' || NULLIF(p_notes, '') || E'\n', '')
    || COALESCE(E'\nUrgent because: ' || v_reason, '');

  v_alert := ava.queue_owner_alert('approval', v_urgent, v_text,
    '[{"text":"✅ Approve","action":"approve"},{"text":"❌ Decline","action":"decline"}]'::jsonb,
    v_id, jsonb_build_object('kind', p_kind));

  RETURN jsonb_build_object(
    'ok', true,
    'booking_id', v_id,
    'status', 'pending_owner_approval',
    'urgent', v_urgent,
    'owner_offline', ava.is_quiet(now()) AND NOT v_urgent,
    'alert_id', v_alert,
    'message', CASE WHEN ava.is_quiet(now())
      THEN 'Request sent. The owner is offline right now and will review it when back (next business morning).'
      ELSE 'Request sent to the owner for approval. The client will be told automatically once it is approved.' END
  );
END $$;

CREATE OR REPLACE FUNCTION claim_due_alerts(p_limit int DEFAULT 20) RETURNS SETOF ava.owner_alerts
LANGUAGE sql AS $$
  UPDATE ava.owner_alerts a SET status = 'sent', sent_at = now()
  WHERE a.id IN (
    SELECT id FROM ava.owner_alerts
    WHERE status = 'queued' AND deliver_after <= now()
    ORDER BY urgent DESC, created_at
    LIMIT p_limit
    FOR UPDATE SKIP LOCKED
  )
  RETURNING a.*
$$;

-- =====================================================================
-- v1.2 - Owner decisions on approval alerts
-- =====================================================================
SET search_path TO ava, public;

INSERT INTO settings (key, value, description) VALUES
  ('owner_test_mode', 'false', 'When true, the owner chat is treated as a client (/testclient)')
ON CONFLICT (key) DO NOTHING;

-- Record the owner's tap and return everything needed to act on it.
-- outcome: approve | decline | stale (request no longer pending) | already_handled | not_found
CREATE OR REPLACE FUNCTION owner_decide(p_alert bigint, p_action text) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  a  ava.owner_alerts;
  b  ava.bookings;
  c  ava.clients;
  sv ava.services;
  o  ava.bookings;
  v_recipient text;
  v_reply_to  text;
  v_thread    text;
BEGIN
  SELECT * INTO a FROM ava.owner_alerts WHERE id = p_alert FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome', 'not_found');
  END IF;

  IF a.acted_at IS NOT NULL THEN
    RETURN jsonb_build_object('outcome', 'already_handled', 'previous_action', a.action,
      'alert_text', a.text, 'telegram_message_id', a.telegram_message_id,
      'owner_chat_id', ava.setting('owner_chat_id') #>> '{}');
  END IF;

  IF a.booking_id IS NOT NULL THEN
    SELECT * INTO b FROM ava.bookings WHERE id = a.booking_id FOR UPDATE;
  END IF;

  -- Late tap on an expired / already-decided request
  IF a.kind = 'approval' AND (b.id IS NULL OR b.status <> 'pending') THEN
    UPDATE ava.owner_alerts SET action = 'stale', acted_at = now() WHERE id = a.id;
    RETURN jsonb_build_object('outcome', 'stale', 'booking_status', b.status,
      'alert_text', a.text, 'telegram_message_id', a.telegram_message_id,
      'owner_chat_id', ava.setting('owner_chat_id') #>> '{}');
  END IF;

  UPDATE ava.owner_alerts SET action = p_action, acted_at = now() WHERE id = a.id;

  SELECT * INTO c  FROM ava.clients  WHERE id = b.client_id;
  SELECT * INTO sv FROM ava.services WHERE id = b.service_id;
  IF b.replaces_booking_id IS NOT NULL THEN
    SELECT * INTO o FROM ava.bookings WHERE id = b.replaces_booking_id;
  END IF;

  -- Where to reply: the client's identifier on the booking channel; for email, the latest inbound message
  SELECT identifier INTO v_recipient FROM ava.client_identifiers
   WHERE client_id = b.client_id AND channel = b.channel ORDER BY created_at DESC LIMIT 1;
  IF b.channel = 'email' THEN
    SELECT external_id, thread_ref INTO v_reply_to, v_thread FROM ava.messages
     WHERE client_id = b.client_id AND channel = 'email' AND direction = 'in'
     ORDER BY created_at DESC LIMIT 1;
  END IF;

  IF p_action = 'decline' THEN
    UPDATE ava.bookings SET status = 'declined', decided_at = now() WHERE id = b.id;
  END IF;

  RETURN jsonb_build_object(
    'outcome', CASE WHEN p_action = 'approve' THEN 'approve' ELSE 'decline' END,
    'alert_text', a.text,
    'telegram_message_id', a.telegram_message_id,
    'owner_chat_id', ava.setting('owner_chat_id') #>> '{}',
    'owner_name', ava.setting('owner_name') #>> '{}',
    'booking_id', b.id,
    'kind', b.kind,
    'client_id', c.id,
    'client_name', COALESCE(c.name, 'there'),
    'client_first_name', COALESCE(split_part(c.name, ' ', 1), 'there'),
    'client_email', COALESCE(c.email, ''),
    'service', COALESCE(sv.name, 'call'),
    'start', b.start_at,
    'end', b.end_at,
    'when_label', ava.fmt_local(b.start_at),
    'duration_min', (extract(epoch FROM b.end_at - b.start_at) / 60)::int,
    'call_format', b.call_format,
    'call_phone', COALESCE(b.call_phone, ''),
    'topic', COALESCE(b.topic, ''),
    'notes', COALESCE(b.notes, ''),
    'channel', b.channel,
    'recipient', COALESCE(v_recipient, ''),
    'reply_to', COALESCE(v_reply_to, ''),
    'thread_ref', COALESCE(v_thread, ''),
    'original_event_id', COALESCE(o.calendar_event_id, ''),
    'original_when_label', CASE WHEN o.id IS NOT NULL THEN ava.fmt_local(o.start_at) ELSE '' END
  );
END $$;

-- Mark an approved booking as booked; a reschedule retires the original booking.
CREATE OR REPLACE FUNCTION finalize_approval(p_booking uuid, p_event text, p_meet text) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE b ava.bookings;
BEGIN
  UPDATE ava.bookings
     SET status = 'approved', decided_at = now(),
         calendar_event_id = NULLIF(p_event, ''), meet_link = NULLIF(p_meet, '')
   WHERE id = p_booking
  RETURNING * INTO b;
  IF b.replaces_booking_id IS NOT NULL THEN
    UPDATE ava.bookings SET status = 'cancelled', updated_at = now()
     WHERE id = b.replaces_booking_id AND status = 'approved';
  END IF;
  RETURN jsonb_build_object('ok', true, 'booking_id', b.id, 'status', b.status);
END $$;

-- Owner commands helper: toggle test mode
CREATE OR REPLACE FUNCTION set_owner_test_mode(p_on boolean) RETURNS boolean
LANGUAGE sql AS $$
  UPDATE ava.settings SET value = to_jsonb(p_on) WHERE key = 'owner_test_mode' RETURNING p_on
$$;

-- =====================================================================
-- v1.3 - Inbound message intake and client profile helpers
-- =====================================================================
SET search_path TO ava, public;

-- Resolve (or create) the client behind an inbound message, log it, and return
-- everything the router and Ava need: block/takeover state, profile, bookings, catalog.
CREATE OR REPLACE FUNCTION ingest_message(
  p_channel text, p_sender text, p_name text, p_text text,
  p_external text DEFAULT NULL, p_thread text DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  v_sender  text := CASE WHEN p_channel = 'email' THEN lower(trim(p_sender)) ELSE trim(p_sender) END;
  v_client  ava.clients;
  v_new     boolean := false;
  v_msg     bigint;
  v_kw      text;
  v_urgent  boolean := false;
  v_blocked boolean;
BEGIN
  SELECT EXISTS (SELECT 1 FROM ava.blocked_senders WHERE channel = p_channel AND identifier = v_sender)
    INTO v_blocked;

  SELECT c.* INTO v_client FROM ava.clients c
    JOIN ava.client_identifiers i ON i.client_id = c.id
   WHERE i.channel = p_channel AND i.identifier = v_sender LIMIT 1;

  IF v_client.id IS NULL AND NOT v_blocked THEN
    INSERT INTO ava.clients (name, email)
    VALUES (NULLIF(trim(p_name), ''), CASE WHEN p_channel = 'email' THEN v_sender END)
    RETURNING * INTO v_client;
    INSERT INTO ava.client_identifiers (client_id, channel, identifier) VALUES (v_client.id, p_channel, v_sender);
    v_new := true;
  END IF;

  INSERT INTO ava.messages (client_id, channel, direction, author, sender_ref, external_id, thread_ref, body, category)
  VALUES (v_client.id, p_channel, 'in', 'client', v_sender, NULLIF(p_external, ''), NULLIF(p_thread, ''), p_text,
          CASE WHEN v_blocked THEN 'blocked' END)
  RETURNING id INTO v_msg;

  IF v_blocked THEN
    RETURN jsonb_build_object('blocked', true, 'message_id', v_msg);
  END IF;

  SELECT string_agg(regexp_replace(k, '([.*+?^${}()|\[\]\\])', '\\\1', 'g'), '|')
    INTO v_kw FROM jsonb_array_elements_text(ava.setting('urgent_keywords')) k;
  IF v_kw IS NOT NULL AND p_text ~* ('\m(' || v_kw || ')\M') THEN
    v_urgent := true;
  END IF;

  RETURN jsonb_build_object(
    'blocked', false,
    'message_id', v_msg,
    'client_id', v_client.id,
    'is_new_client', v_new,
    'is_existing_client', v_client.is_existing,
    'takeover_active', COALESCE(v_client.takeover_until > now(), false),
    'quiet_now', ava.is_quiet(now()),
    'urgent_words', v_urgent,
    'persona_name', ava.setting('persona_name') #>> '{}',
    'owner_name', ava.setting('owner_name') #>> '{}',
    'timezone', ava.setting('timezone') #>> '{}',
    'now_label', trim(to_char(now() AT TIME ZONE (ava.setting('timezone') #>> '{}'), 'FMDay, FMMonth FMDD, YYYY FMHH12:MI AM')),
    'today', (now() AT TIME ZONE (ava.setting('timezone') #>> '{}'))::date,
    'profile', jsonb_build_object(
      'name', v_client.name, 'email', v_client.email, 'phone', v_client.phone,
      'company', v_client.company, 'found_via', v_client.found_via, 'notes', v_client.notes),
    'bookings', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'booking_id', b.id, 'status', b.status, 'service', s.name,
        'when', ava.fmt_local(b.start_at) || ' ET', 'start', b.start_at, 'end', b.end_at,
        'call_format', b.call_format,
        'hours_until', round(extract(epoch FROM b.start_at - now()) / 3600)) ORDER BY b.start_at)
      FROM ava.bookings b LEFT JOIN ava.services s ON s.id = b.service_id
      WHERE b.client_id = v_client.id AND b.status IN ('pending', 'approved') AND b.end_at > now()), '[]'::jsonb),
    'services', (
      SELECT string_agg('- ' || name || ' (' || duration_min || ' min' ||
               CASE audience WHEN 'existing' THEN ', existing clients only' WHEN 'new' THEN ', new clients' ELSE '' END ||
               '): ' || COALESCE(description, ''), E'\n' ORDER BY sort_order)
      FROM ava.services WHERE active)
  );
END $$;

-- Fill in profile fields Ava learned; never overwrite a known value with a blank.
CREATE OR REPLACE FUNCTION update_client_profile(
  p_client uuid, p_name text, p_email text, p_phone text, p_company text, p_found_via text
) RETURNS void
LANGUAGE plpgsql AS $$
BEGIN
  UPDATE ava.clients SET
    name      = COALESCE(NULLIF(trim(p_name), ''), name),
    email     = COALESCE(NULLIF(lower(trim(p_email)), ''), email),
    phone     = COALESCE(NULLIF(trim(p_phone), ''), phone),
    company   = COALESCE(NULLIF(trim(p_company), ''), company),
    found_via = COALESCE(NULLIF(trim(p_found_via), ''), found_via)
  WHERE id = p_client;
  -- A newly learned email becomes another way to recognise this client
  IF NULLIF(trim(p_email), '') IS NOT NULL THEN
    INSERT INTO ava.client_identifiers (client_id, channel, identifier)
    VALUES (p_client, 'email', lower(trim(p_email)))
    ON CONFLICT (channel, identifier) DO NOTHING;
  END IF;
END $$;

CREATE OR REPLACE FUNCTION set_message_category(p_message bigint, p_category text) RETURNS void
LANGUAGE sql AS $$ UPDATE ava.messages SET category = p_category WHERE id = p_message $$;

-- =====================================================================
-- v1.4 - Owner commands (/testclient, /takeover, /say, /resume, /help)
-- =====================================================================
SET search_path TO ava, public;

CREATE OR REPLACE FUNCTION owner_command(p_cmd text, p_args text) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  v_cmd   text := lower(split_part(trim(p_cmd), '@', 1));   -- "/say@MyBot" -> "/say"
  v_hours int  := (ava.setting('takeover_resume_hours') #>> '{}')::int;
  v_on    boolean;
  c       ava.clients;
  m       ava.messages;
  v_names text;
  v_help  text := E'Owner commands:\n'
    || E'/testclient - switch between owner mode and chatting with Ava as a client\n'
    || E'/takeover - take over the most recent client conversation (Ava goes quiet)\n'
    || E'/say <message> - send a message to the client you took over\n'
    || E'/resume - hand all taken-over conversations back to Ava\n'
    || E'/help - show this list';
BEGIN
  IF v_cmd = '/testclient' THEN
    v_on := NOT COALESCE((ava.setting('owner_test_mode') #>> '{}')::boolean, false);
    PERFORM ava.set_owner_test_mode(v_on);
    RETURN jsonb_build_object('reply', CASE WHEN v_on
      THEN E'🧪 Test client mode ON. Your messages now go to Ava as a client.\nSend /testclient again to switch back to owner mode.'
      ELSE '👤 Owner mode ON. Your messages are no longer sent to Ava.' END);

  ELSIF v_cmd = '/takeover' THEN
    SELECT * INTO m FROM ava.messages
     WHERE direction = 'in' AND author = 'client' AND client_id IS NOT NULL
       AND created_at > now() - interval '7 days' AND COALESCE(category, '') NOT IN ('spam', 'blocked')
     ORDER BY created_at DESC LIMIT 1;
    IF m.id IS NULL THEN
      RETURN jsonb_build_object('reply', 'No client has messaged in the last 7 days, so there is nothing to take over.');
    END IF;
    UPDATE ava.clients SET takeover_until = now() + make_interval(hours => v_hours)
     WHERE id = m.client_id RETURNING * INTO c;
    RETURN jsonb_build_object('reply',
      '🙋 You have taken over the conversation with ' || COALESCE(c.name, 'the client') || ' (' || m.channel || E').\n'
      || 'Ava stays quiet and their messages come straight to you for ' || v_hours || E' hours.\n'
      || E'Reply with /say <message> to answer them, or /resume to hand back to Ava.');

  ELSIF v_cmd = '/say' THEN
    IF COALESCE(trim(p_args), '') = '' THEN
      RETURN jsonb_build_object('reply', 'Add your message after the command, for example: /say Thanks, I will call you at 2pm.');
    END IF;
    SELECT * INTO c FROM ava.clients WHERE takeover_until > now() ORDER BY updated_at DESC LIMIT 1;
    IF c.id IS NULL THEN
      RETURN jsonb_build_object('reply', 'No active takeover. Send /takeover first.');
    END IF;
    SELECT * INTO m FROM ava.messages
     WHERE client_id = c.id AND direction = 'in' ORDER BY created_at DESC LIMIT 1;
    UPDATE ava.clients SET takeover_until = now() + make_interval(hours => v_hours) WHERE id = c.id;
    RETURN jsonb_build_object(
      'reply', '✓ Sent to ' || COALESCE(c.name, 'the client') || '.',
      'send', jsonb_build_object(
        'client_id', c.id,
        'channel', m.channel,
        'recipient', COALESCE((SELECT identifier FROM ava.client_identifiers
                                WHERE client_id = c.id AND channel = m.channel
                                ORDER BY created_at DESC LIMIT 1), m.sender_ref),
        'text', trim(p_args),
        'reply_to', COALESCE(m.external_id, ''),
        'thread_ref', COALESCE(m.thread_ref, '')));

  ELSIF v_cmd = '/resume' THEN
    WITH r AS (
      UPDATE ava.clients SET takeover_until = NULL WHERE takeover_until > now() RETURNING COALESCE(name, 'unnamed client') AS n
    ) SELECT string_agg(n, ', ') INTO v_names FROM r;
    RETURN jsonb_build_object('reply', CASE WHEN v_names IS NULL
      THEN 'Ava was not paused for anyone.'
      ELSE '🤖 Ava is back on for: ' || v_names || '.' END);

  ELSE
    RETURN jsonb_build_object('reply', v_help);
  END IF;
END $$;

-- =====================================================================
-- v1.5 - Separate conversations per client, with summaries of past ones
-- A conversation closes after N hours of silence, or when its booking
-- request is approved, declined or expires. Ava's working memory is keyed
-- on the conversation; older conversations reach her only as summaries.
-- =====================================================================
SET search_path TO ava, public;

INSERT INTO settings (key, value, description) VALUES
  ('conversation_gap_hours', '12', 'Silence after which the next message starts a new conversation')
ON CONFLICT (key) DO NOTHING;

CREATE TABLE IF NOT EXISTS conversations (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  client_id        uuid NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  channel          text NOT NULL,
  status           text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed')),
  started_at       timestamptz NOT NULL DEFAULT now(),
  last_message_at  timestamptz NOT NULL DEFAULT now(),
  closed_at        timestamptz,
  close_reason     text,              -- inactive | booking_approved | booking_declined | booking_expired
  summary          text,              -- written when closed
  summarized_at    timestamptz
);
CREATE INDEX IF NOT EXISTS conversations_client_idx ON conversations(client_id, started_at DESC);
CREATE INDEX IF NOT EXISTS conversations_open_idx   ON conversations(client_id) WHERE status = 'open';

ALTER TABLE messages ADD COLUMN IF NOT EXISTS conversation_id uuid REFERENCES conversations(id);
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS conversation_id uuid REFERENCES conversations(id);
CREATE INDEX IF NOT EXISTS messages_conversation_idx ON messages(conversation_id, created_at);

-- Close a client's open conversations that have gone quiet; return the open (or a new) one.
CREATE OR REPLACE FUNCTION current_conversation(p_client uuid, p_channel text) RETURNS uuid
LANGUAGE plpgsql AS $$
DECLARE
  gap  interval := make_interval(hours => COALESCE((ava.setting('conversation_gap_hours') #>> '{}')::int, 12));
  v_id uuid;
BEGIN
  UPDATE ava.conversations
     SET status = 'closed', closed_at = last_message_at + gap, close_reason = 'inactive'
   WHERE client_id = p_client AND status = 'open' AND last_message_at < now() - gap;

  SELECT id INTO v_id FROM ava.conversations
   WHERE client_id = p_client AND status = 'open'
   ORDER BY last_message_at DESC LIMIT 1;

  IF v_id IS NULL THEN
    INSERT INTO ava.conversations (client_id, channel) VALUES (p_client, p_channel) RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END $$;

-- Every message is filed under the client's open conversation (inbound opens one if needed).
CREATE OR REPLACE FUNCTION tag_message_conversation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.conversation_id IS NULL AND NEW.client_id IS NOT NULL THEN
    IF NEW.direction = 'in' THEN
      NEW.conversation_id := ava.current_conversation(NEW.client_id, NEW.channel);
    ELSE
      SELECT id INTO NEW.conversation_id FROM ava.conversations
       WHERE client_id = NEW.client_id AND status = 'open'
       ORDER BY last_message_at DESC LIMIT 1;
    END IF;
  END IF;
  IF NEW.conversation_id IS NOT NULL THEN
    UPDATE ava.conversations SET last_message_at = NEW.created_at WHERE id = NEW.conversation_id;
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS messages_conversation ON messages;
CREATE TRIGGER messages_conversation BEFORE INSERT ON messages
  FOR EACH ROW EXECUTE FUNCTION tag_message_conversation();

-- A booking request belongs to the conversation that produced it.
CREATE OR REPLACE FUNCTION tag_booking_conversation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.conversation_id IS NULL THEN
    SELECT id INTO NEW.conversation_id FROM ava.conversations
     WHERE client_id = NEW.client_id AND status = 'open'
     ORDER BY last_message_at DESC LIMIT 1;
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS bookings_conversation ON bookings;
CREATE TRIGGER bookings_conversation BEFORE INSERT ON bookings
  FOR EACH ROW EXECUTE FUNCTION tag_booking_conversation();

-- When a request is decided or expires, its conversation is finished.
CREATE OR REPLACE FUNCTION close_conversation_on_decision() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.status = 'pending' AND NEW.status IN ('approved', 'declined', 'expired') AND NEW.conversation_id IS NOT NULL THEN
    UPDATE ava.conversations
       SET status = 'closed', closed_at = now(), close_reason = 'booking_' || NEW.status
     WHERE id = NEW.conversation_id AND status = 'open';
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS bookings_close_conversation ON bookings;
CREATE TRIGGER bookings_close_conversation AFTER UPDATE OF status ON bookings
  FOR EACH ROW EXECUTE FUNCTION close_conversation_on_decision();

-- Closed conversations that still need a summary (oldest first)
CREATE OR REPLACE FUNCTION conversations_needing_summary(p_client uuid DEFAULT NULL, p_limit int DEFAULT 5)
RETURNS TABLE (conversation_id uuid)
LANGUAGE sql STABLE AS $$
  SELECT c.id FROM ava.conversations c
   WHERE c.status = 'closed' AND c.summary IS NULL
     AND (p_client IS NULL OR c.client_id = p_client)
     AND EXISTS (SELECT 1 FROM ava.messages m WHERE m.conversation_id = c.id)
   ORDER BY c.closed_at
   LIMIT p_limit
$$;

-- Transcript for the summarizer
CREATE OR REPLACE FUNCTION conversation_transcript(p_conversation uuid) RETURNS jsonb
LANGUAGE sql STABLE AS $$
  SELECT jsonb_build_object(
    'conversation_id', c.id,
    'client_name', cl.name,
    'started', ava.fmt_local(c.started_at),
    'close_reason', c.close_reason,
    'bookings', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'service', s.name, 'when', ava.fmt_local(b.start_at) || ' ET', 'status', b.status))
      FROM ava.bookings b LEFT JOIN ava.services s ON s.id = b.service_id
      WHERE b.conversation_id = c.id), '[]'::jsonb),
    'transcript', COALESCE((SELECT string_agg(
        CASE m.author WHEN 'client' THEN 'Client' WHEN 'owner' THEN 'Owner' ELSE 'Assistant' END
        || ': ' || left(regexp_replace(m.body, '\s+', ' ', 'g'), 600), E'\n' ORDER BY m.created_at)
      FROM ava.messages m WHERE m.conversation_id = c.id AND m.body IS NOT NULL), '')
  )
  FROM ava.conversations c JOIN ava.clients cl ON cl.id = c.client_id
  WHERE c.id = p_conversation
$$;

CREATE OR REPLACE FUNCTION save_conversation_summary(p_conversation uuid, p_summary text) RETURNS void
LANGUAGE sql AS $$
  UPDATE ava.conversations SET summary = left(trim(p_summary), 600), summarized_at = now() WHERE id = p_conversation
$$;

-- What Ava sees about earlier conversations (newest first)
CREATE OR REPLACE FUNCTION conversation_history(p_client uuid, p_current uuid, p_limit int DEFAULT 5) RETURNS jsonb
LANGUAGE sql STABLE AS $$
  SELECT COALESCE(jsonb_agg(h ORDER BY h->>'started_at' DESC), '[]'::jsonb) FROM (
    SELECT jsonb_build_object(
      'started_at', c.started_at,
      'date', trim(to_char(c.started_at AT TIME ZONE (ava.setting('timezone') #>> '{}'), 'Mon FMDD, YYYY')),
      'channel', c.channel,
      'summary', COALESCE(c.summary, '(no summary yet)')) AS h
    FROM ava.conversations c
    WHERE c.client_id = p_client AND c.id <> p_current AND c.status = 'closed'
      AND EXISTS (SELECT 1 FROM ava.messages m WHERE m.conversation_id = c.id)
    ORDER BY c.started_at DESC LIMIT p_limit
  ) x
$$;

-- Backfill: give existing messages a conversation per client so history starts clean
DO $$
DECLARE r record; v_conv uuid;
BEGIN
  FOR r IN SELECT DISTINCT client_id, min(channel) AS channel, min(created_at) AS first_at, max(created_at) AS last_at
             FROM ava.messages WHERE conversation_id IS NULL AND client_id IS NOT NULL GROUP BY client_id LOOP
    INSERT INTO ava.conversations (client_id, channel, status, started_at, last_message_at, closed_at, close_reason)
    VALUES (r.client_id, r.channel, 'closed', r.first_at, r.last_at, now(), 'inactive')
    RETURNING id INTO v_conv;
    UPDATE ava.messages SET conversation_id = v_conv WHERE client_id = r.client_id AND conversation_id IS NULL;
  END LOOP;
END $$;

-- ingest_message now reports the conversation and any summaries still owed
CREATE OR REPLACE FUNCTION ingest_message(
  p_channel text, p_sender text, p_name text, p_text text,
  p_external text DEFAULT NULL, p_thread text DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  v_sender  text := CASE WHEN p_channel = 'email' THEN lower(trim(p_sender)) ELSE trim(p_sender) END;
  v_client  ava.clients;
  v_new     boolean := false;
  v_msg     bigint;
  v_conv    uuid;
  v_kw      text;
  v_urgent  boolean := false;
  v_blocked boolean;
BEGIN
  SELECT EXISTS (SELECT 1 FROM ava.blocked_senders WHERE channel = p_channel AND identifier = v_sender)
    INTO v_blocked;

  SELECT c.* INTO v_client FROM ava.clients c
    JOIN ava.client_identifiers i ON i.client_id = c.id
   WHERE i.channel = p_channel AND i.identifier = v_sender LIMIT 1;

  IF v_client.id IS NULL AND NOT v_blocked THEN
    INSERT INTO ava.clients (name, email)
    VALUES (NULLIF(trim(p_name), ''), CASE WHEN p_channel = 'email' THEN v_sender END)
    RETURNING * INTO v_client;
    INSERT INTO ava.client_identifiers (client_id, channel, identifier) VALUES (v_client.id, p_channel, v_sender);
    v_new := true;
  END IF;

  INSERT INTO ava.messages (client_id, channel, direction, author, sender_ref, external_id, thread_ref, body, category)
  VALUES (v_client.id, p_channel, 'in', 'client', v_sender, NULLIF(p_external, ''), NULLIF(p_thread, ''), p_text,
          CASE WHEN v_blocked THEN 'blocked' END)
  RETURNING id, conversation_id INTO v_msg, v_conv;

  IF v_blocked THEN
    RETURN jsonb_build_object('blocked', true, 'message_id', v_msg);
  END IF;

  SELECT string_agg(regexp_replace(k, '([.*+?^${}()|\[\]\\])', '\\\1', 'g'), '|')
    INTO v_kw FROM jsonb_array_elements_text(ava.setting('urgent_keywords')) k;
  IF v_kw IS NOT NULL AND p_text ~* ('\m(' || v_kw || ')\M') THEN
    v_urgent := true;
  END IF;

  RETURN jsonb_build_object(
    'blocked', false,
    'message_id', v_msg,
    'client_id', v_client.id,
    'conversation_id', v_conv,
    'is_new_conversation', (SELECT count(*) = 1 FROM ava.messages WHERE conversation_id = v_conv),
    'needs_summary', COALESCE((SELECT jsonb_agg(n.conversation_id) FROM ava.conversations_needing_summary(v_client.id) n), '[]'::jsonb),
    'is_new_client', v_new,
    'is_existing_client', v_client.is_existing,
    'takeover_active', COALESCE(v_client.takeover_until > now(), false),
    'quiet_now', ava.is_quiet(now()),
    'urgent_words', v_urgent,
    'persona_name', ava.setting('persona_name') #>> '{}',
    'owner_name', ava.setting('owner_name') #>> '{}',
    'timezone', ava.setting('timezone') #>> '{}',
    'now_label', trim(to_char(now() AT TIME ZONE (ava.setting('timezone') #>> '{}'), 'FMDay, FMMonth FMDD, YYYY FMHH12:MI AM')),
    'today', (now() AT TIME ZONE (ava.setting('timezone') #>> '{}'))::date,
    'profile', jsonb_build_object(
      'name', v_client.name, 'email', v_client.email, 'phone', v_client.phone,
      'company', v_client.company, 'found_via', v_client.found_via, 'notes', v_client.notes),
    'bookings', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'booking_id', b.id, 'status', b.status, 'service', s.name,
        'when', ava.fmt_local(b.start_at) || ' ET', 'start', b.start_at, 'end', b.end_at,
        'call_format', b.call_format,
        'hours_until', round(extract(epoch FROM b.start_at - now()) / 3600)) ORDER BY b.start_at)
      FROM ava.bookings b LEFT JOIN ava.services s ON s.id = b.service_id
      WHERE b.client_id = v_client.id AND b.status IN ('pending', 'approved') AND b.end_at > now()), '[]'::jsonb),
    'services', (
      SELECT string_agg('- ' || name || ' (' || duration_min || ' min' ||
               CASE audience WHEN 'existing' THEN ', existing clients only' WHEN 'new' THEN ', new clients' ELSE '' END ||
               '): ' || COALESCE(description, ''), E'\n' ORDER BY sort_order)
      FROM ava.services WHERE active)
  );
END $$;

-- =====================================================================
-- v1.7 - Spam actions and Ava-handled reschedule / cancel
-- =====================================================================
SET search_path TO ava, public;

CREATE OR REPLACE FUNCTION owner_decide(p_alert bigint, p_action text) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  a  ava.owner_alerts;
  b  ava.bookings;
  c  ava.clients;
  sv ava.services;
  o  ava.bookings;
  v_recipient text;
  v_reply_to  text;
  v_thread    text;
  se ava.spam_events;
  sm ava.messages;
  sc ava.clients;
BEGIN
  SELECT * INTO a FROM ava.owner_alerts WHERE id = p_alert FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome', 'not_found');
  END IF;

  IF a.acted_at IS NOT NULL THEN
    RETURN jsonb_build_object('outcome', 'already_handled', 'previous_action', a.action,
      'alert_text', a.text, 'telegram_message_id', a.telegram_message_id,
      'owner_chat_id', ava.setting('owner_chat_id') #>> '{}');
  END IF;

  -- Spam alerts: brush_off | ignore | not_spam
  IF a.kind = 'spam' THEN
    UPDATE ava.owner_alerts SET action = p_action, acted_at = now() WHERE id = a.id;
    UPDATE ava.spam_events
       SET action = CASE p_action WHEN 'brush_off' THEN 'brushed_off' WHEN 'not_spam' THEN 'not_spam' ELSE 'ignored' END
     WHERE id = (a.ref ->> 'spam_event_id')::bigint
    RETURNING * INTO se;
    SELECT * INTO sm FROM ava.messages WHERE id = se.message_id;
    SELECT * INTO sc FROM ava.clients WHERE id = sm.client_id;
    IF p_action = 'not_spam' THEN
      UPDATE ava.messages SET category = 'not_spam' WHERE id = sm.id;
    END IF;
    RETURN jsonb_build_object(
      'outcome', 'spam_' || p_action,
      'alert_text', a.text,
      'telegram_message_id', a.telegram_message_id,
      'owner_chat_id', ava.setting('owner_chat_id') #>> '{}',
      'client_id', sm.client_id,
      'client_name', COALESCE(sc.name, ''),
      'channel', sm.channel,
      'recipient', COALESCE(sm.sender_ref, ''),
      'reply_to', COALESCE(sm.external_id, ''),
      'thread_ref', COALESCE(sm.thread_ref, ''),
      'original_text', COALESCE(sm.body, ''));
  END IF;

  IF a.booking_id IS NOT NULL THEN
    SELECT * INTO b FROM ava.bookings WHERE id = a.booking_id FOR UPDATE;
  END IF;

  -- Late tap on an expired / already-decided request
  IF a.kind IN ('approval', 'reminder') AND (b.id IS NULL OR b.status <> 'pending') THEN
    UPDATE ava.owner_alerts SET action = 'stale', acted_at = now() WHERE id = a.id;
    RETURN jsonb_build_object('outcome', 'stale', 'booking_status', b.status,
      'alert_text', a.text, 'telegram_message_id', a.telegram_message_id,
      'owner_chat_id', ava.setting('owner_chat_id') #>> '{}');
  END IF;

  UPDATE ava.owner_alerts SET action = p_action, acted_at = now() WHERE id = a.id;

  SELECT * INTO c  FROM ava.clients  WHERE id = b.client_id;
  SELECT * INTO sv FROM ava.services WHERE id = b.service_id;
  IF b.replaces_booking_id IS NOT NULL THEN
    SELECT * INTO o FROM ava.bookings WHERE id = b.replaces_booking_id;
  END IF;

  -- Where to reply: the client's identifier on the booking channel; for email, the latest inbound message
  SELECT identifier INTO v_recipient FROM ava.client_identifiers
   WHERE client_id = b.client_id AND channel = b.channel ORDER BY created_at DESC LIMIT 1;
  IF b.channel = 'email' THEN
    SELECT external_id, thread_ref INTO v_reply_to, v_thread FROM ava.messages
     WHERE client_id = b.client_id AND channel = 'email' AND direction = 'in'
     ORDER BY created_at DESC LIMIT 1;
  END IF;

  IF p_action = 'decline' THEN
    UPDATE ava.bookings SET status = 'declined', decided_at = now() WHERE id = b.id;
  END IF;

  RETURN jsonb_build_object(
    'outcome', CASE WHEN p_action = 'approve' THEN 'approve' ELSE 'decline' END,
    'alert_text', a.text,
    'telegram_message_id', a.telegram_message_id,
    'owner_chat_id', ava.setting('owner_chat_id') #>> '{}',
    'owner_name', ava.setting('owner_name') #>> '{}',
    'booking_id', b.id,
    'kind', b.kind,
    'client_id', c.id,
    'client_name', COALESCE(c.name, 'there'),
    'client_first_name', COALESCE(split_part(c.name, ' ', 1), 'there'),
    'client_email', COALESCE(c.email, ''),
    'service', COALESCE(sv.name, 'call'),
    'start', b.start_at,
    'end', b.end_at,
    'when_label', ava.fmt_local(b.start_at),
    'duration_min', (extract(epoch FROM b.end_at - b.start_at) / 60)::int,
    'call_format', b.call_format,
    'call_phone', COALESCE(b.call_phone, ''),
    'topic', COALESCE(b.topic, ''),
    'notes', COALESCE(b.notes, ''),
    'channel', b.channel,
    'recipient', COALESCE(v_recipient, ''),
    'reply_to', COALESCE(v_reply_to, ''),
    'thread_ref', COALESCE(v_thread, ''),
    'original_event_id', COALESCE(o.calendar_event_id, ''),
    'original_when_label', CASE WHEN o.id IS NOT NULL THEN ava.fmt_local(o.start_at) ELSE '' END
  );
END $$;


-- =====================================================================
-- Booking changes requested through Ava (reschedule / cancel)
-- outcome: not_found | not_changeable | within_cutoff | cancelled | reschedule_ok
-- =====================================================================
CREATE OR REPLACE FUNCTION request_booking_change(p_action text, p_booking uuid, p_client uuid) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  b       ava.bookings;
  c       ava.clients;
  sv      ava.services;
  cutoff  interval := make_interval(hours => COALESCE((ava.setting('change_cutoff_hours') #>> '{}')::int, 24));
  v_owner text := ava.setting('owner_name') #>> '{}';
  v_what  text := CASE WHEN p_action = 'cancel' THEN 'cancel' ELSE 'move' END;
BEGIN
  SELECT * INTO b FROM ava.bookings WHERE id = p_booking AND client_id = p_client FOR UPDATE;
  IF b.id IS NULL THEN
    RETURN jsonb_build_object('outcome', 'not_found',
      'message', 'No booking with that id belongs to this client. Use a booking_id from the upcoming calls list.');
  END IF;
  SELECT * INTO c  FROM ava.clients  WHERE id = b.client_id;
  SELECT * INTO sv FROM ava.services WHERE id = b.service_id;

  IF b.status NOT IN ('approved', 'pending') OR b.start_at <= now() THEN
    RETURN jsonb_build_object('outcome', 'not_changeable',
      'message', 'That call is ' || b.status || ' and cannot be changed.');
  END IF;

  -- Inside the cutoff the owner decides: alert him (urgent) and change nothing
  IF b.start_at - now() < cutoff THEN
    PERFORM ava.queue_owner_alert('client_msg', true,
      '🔁 ' || COALESCE(c.name, 'A client') || ' wants to ' || v_what || ' a call within ' || extract(epoch FROM cutoff)::int / 3600 || E'h\n\n'
      || COALESCE(sv.name, 'Call') || ', ' || ava.fmt_local(b.start_at) || E' ET\n'
      || 'Nothing was changed. Please handle it directly (/takeover then /say).', NULL, b.id);
    RETURN jsonb_build_object('outcome', 'within_cutoff',
      'message', 'The call is less than ' || extract(epoch FROM cutoff)::int / 3600 || ' hours away, so changes go to ' || v_owner
        || ' personally. ' || v_owner || ' has been alerted and will get back to the client directly. Nothing was changed yet.');
  END IF;

  IF p_action = 'cancel' THEN
    UPDATE ava.bookings SET status = CASE WHEN status = 'pending' THEN 'declined' ELSE 'cancelled' END,
                            decided_at = now()
     WHERE id = b.id;
    PERFORM ava.queue_owner_alert('cancel', false,
      '❎ ' || COALESCE(c.name, 'A client') || E' cancelled\n\n' || COALESCE(sv.name, 'Call') || ', ' || ava.fmt_local(b.start_at)
      || E' ET\nThe calendar event was removed.', NULL, b.id);
    RETURN jsonb_build_object('outcome', 'cancelled', 'event_id', COALESCE(b.calendar_event_id, ''),
      'message', 'Cancelled. The calendar invite has been withdrawn and ' || v_owner || ' has been notified.');
  END IF;

  -- Reschedule: hand back what the booking request needs
  IF b.status <> 'approved' THEN
    RETURN jsonb_build_object('outcome', 'not_changeable',
      'message', 'That request is still waiting for ' || v_owner || '''s approval. Offer to cancel it and request the new time instead.');
  END IF;
  RETURN jsonb_build_object('outcome', 'reschedule_ok',
    'booking_id', b.id, 'service', COALESCE(sv.name, ''), 'call_format', b.call_format,
    'call_phone', COALESCE(b.call_phone, ''), 'topic', COALESCE(b.topic, ''), 'notes', COALESCE(b.notes, ''),
    'channel', b.channel, 'duration_min', (extract(epoch FROM b.end_at - b.start_at) / 60)::int);
END $$;
